<?php
require_once '../includes/funcoes.php';exigir_admin();if(isset($_GET['excluir'])){$pdo->prepare("DELETE FROM marcas WHERE id=?")->execute([(int)$_GET['excluir']]);log_acao('Marca excluída');header('Location: marcas.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && trim($_POST['nome']??'')){$pdo->prepare("INSERT INTO marcas(nome) VALUES(?)")->execute([trim($_POST['nome'])]);log_acao('Marca cadastrada');header('Location: marcas.php');exit;}
$rows=$pdo->query("SELECT * FROM marcas ORDER BY nome")->fetchAll();$titulo='Marcas';require '../includes/header.php';?>
<div class="admin-shell"><?php require '_menu.php';?><section><h1 class="section-title">Marcas</h1><div class="panel mb-3"><form method="post" class="d-flex gap-2"><input class="form-control" name="nome" placeholder="Nova marca" required><button class="btn btn-lumia">Adicionar</button></form></div><div class="panel"><table class="table datatable"><thead><tr><th>Marca</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nome'])?></td><td><a class="text-danger" data-confirm="Excluir marca?" href="?excluir=<?=$r['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require '../includes/footer.php';?>
